CREATE SCHEMA other; CREATE VIEW public.dv AS SELECT vin FROM public.vin_decodes; REVOKE ALL ON public.dv FROM PUBLIC, anon, authenticated; CREATE TABLE other.dv (vin text); GRANT USAGE ON SCHEMA other TO anon; GRANT SELECT ON other.dv TO anon; CREATE FUNCTION public.g() RETURNS bigint LANGUAGE sql SECURITY DEFINER SET search_path = '' AS $q$ SELECT count(*) FROM other.dv $q$; GRANT EXECUTE ON FUNCTION public.g() TO anon;
